-- ============================================================
-- LOT 8 — Écran « Protocoles » (Référentiel) : données par défaut
--
-- Spec : .kiro/specs/referentiel-protocoles/ (US9, RG1/RG2/RG3/RG4/RG8/RG9/RG10).
--
-- Transcription des 6 protocoles PDF (.tmp-protocoles/*.txt) vers
-- ref_exercices + ref_exercice_sets :
--   Arraché -> exercice_type SN (reference SN)
--   Épaulé  -> exercice_type CL (reference CJ)
--   Jeté    -> exercice_type JK (reference CJ)
--   Squat   -> exercice_type SQ (reference BS=Flexion Nuque / FS=Flexion Clavicule)
--   Tirage  -> exercice_type PL (reference SN=Tirage Arraché / CJ=Tirage Épaulé)
--   Muscu   -> exercice_type MS (reference NULL, weight NULL)
--
-- Règles appliquées :
--   RG2  semaine type : Foncier=F, Technique=T, Surcharge=S, Affûtage=A, Deload=D.
--   RG3  objectif : technique EXT/CATCH/PATH ; squat-tirage KEEP/STR/SPD ;
--        muscu GEN/LEGS/POST/UPPER.
--   RG9  groupes archétypes : « Mixte & Cyclique » -> MID+CYCLE ; « Bourrin » ->
--        ROUGH ; « Technicien & Apprentissage » -> TECH+LEARN.
--   RG8  Musculation dupliquée sur 5 semaines types (F,T,S,A,D) × 5 archétypes,
--        poids et référence NULL.
--   RG10 « ou » : une ligne ref_exercices par alternative (même training_order).
--   rep_number = label brut VARCHAR (ex. '6', '30s', '(1 + 1)', '2 (1 + 1)', NULL) ;
--        on ne calcule plus un entier (réinterprétation learning.md 2026-08-18).
--   weight = pourcentage de l'exercice de référence (NULL pour la Musculation).
--
-- Volume généré : 555 ref_exercices, 3223 ref_exercice_sets.
--   SN=60ex,350sets / CL=60ex,360sets / JK=60ex,360sets / SQ=45ex,364sets / PL=45ex,364sets / MS=285ex,1425sets
--
-- Idempotent : ids GENERATED BY DEFAULT AS IDENTITY (non forcés) ; purge ciblée
-- (DELETE sets puis exercices sur les exercice_type alimentés) avant ré-insertion,
-- donc rejouable sans doublon. ⚠️ La purge retire aussi d'éventuelles lignes de
-- ces types saisies manuellement (seed de référence, cf. pattern ecran_planning).
--
-- Rollback : back-end/src/main/resources/db/rollback/V20261019_120000__protocoles_data.sql
-- ============================================================


-- ------------------------------------------------------------
-- Purge idempotente (dépendances : sets avant exercices).
-- ------------------------------------------------------------
DELETE FROM ref_exercice_sets
 WHERE ref_exercice_id IN (
     SELECT ref_exercice_id FROM ref_exercices
      WHERE exercice_type IN ('SN', 'CL', 'JK', 'SQ', 'PL', 'MS')
 );

DELETE FROM ref_exercices
 WHERE exercice_type IN ('SN', 'CL', 'JK', 'SQ', 'PL', 'MS');


-- ============================================================
-- Arraché (SN) — 60 exercices, 350 sets
-- ============================================================

-- F / EXT / séance 1 : 3 x (1 Tirage Haut Arraché + 1 Arraché Debout Suspension)
WITH ins AS (
    INSERT INTO ref_exercices (exercice_type, week_type, goal, training_order, exercice_name, reference)
    VALUES ('SN', 'F', 'EXT', 1, '3 x (1 Tirage Haut Arraché + 1 Arraché Debout Suspension)', 'SN')
    RETURNING ref_exercice_id
)
INSERT INTO ref_exercice_sets (ref_exercice_id, archetype, set_number, rep_number, weight)
    SELECT ref_exercice_id, 'MID', 3, NULL, 75 FROM ins
UNION ALL
    SELECT ref_exercice_id, 'CYCLE', 3, NULL, 75 FROM ins
UNION ALL
    SELECT ref_exercice_id, 'ROUGH', 5, NULL, 75 FROM ins
UNION ALL
    SELECT ref_exercice_id, 'TECH', 4, NULL, 75 FROM ins
UNION ALL
    SELECT ref_exercice_id, 'LEARN', 4, NULL, 75 FROM ins;

